on conflict (slug) do update set
name=excluded.name,description=excluded.description,base_price=excluded.base_price,category=excluded.category,
service_type=excluded.service_type,unit=excluded.unit,market_price=excluded.market_price,is_add_on=excluded.is_add_on,
frequency=excluded.frequency,bundle_services=excluded.bundle_services,active=true;